        char * le;
        char * v;
        char * ve;
        size_t vl;
        ls = p;
        le = p;
        while (((le < end) && ((*le) != '\n'))) {
            le = (le + 1);
        }
        p = ((le < end) ? (le + 1) : end);
        while (((ls < le) && (((*ls) == ' ') || ((*ls) == '\t')))) {
            ls = (ls + 1);
        }
        if ((((size_t)((le - ls)) < 4) || (strncmp(ls, "dep", 3) != 0))) {
            continue;
        }
        v = (ls + 3);
